<?php require_once __DIR__.'/../includes/layout.php'; require_permission('activity.view'); $rows=db()->query('SELECT a.*,u.username FROM activity_logs a LEFT JOIN users u ON u.id=a.user_id ORDER BY a.created_at DESC LIMIT 300')->fetchAll(); dashboard_header('Activity Log'); ?><div class="glass-card p-4"><div class="table-responsive"><table class="table"><tr><th>Date</th><th>User</th><th>Action</th><th>Entity</th><th>IP</th></tr><?php foreach($rows as $r):?><tr><td><?=e($r['created_at'])?></td><td><?=e($r['username'])?></td><td><?=e($r['action'])?></td><td><?=e($r['entity'])?> #<?=e((string)$r['entity_id'])?></td><td><?=e($r['ip_address'])?></td></tr><?php endforeach;?></table></div></div><?php dashboard_footer(); ?>
